// Regenerates seed/data modules from extraction JSON (/tmp/extracted/*.json,
// produced by the one-off bundle-extraction scripts). The generated data.ts
// files are committed source — editing them directly is the normal path.
// Idempotent; only re-run after refreshing /tmp/extracted.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs'

const E = '/tmp/extracted'
const read = (f) => JSON.parse(readFileSync(`${E}/${f}`, 'utf8'))
const banner = (src) => `/**
 * GENERATED by scripts/sync-extracted.mjs — content extracted from the original
 * macos27 bundle. Edit /tmp/extracted/*.json + re-run the script instead of editing.
 * Source: ${src}
 */
`

// ---------- fs-seed.ts ----------
{
  const nodes = read('fs-seeds.json')
  const baseFolders = [
    ['root', null, '/'], ['applications', 'root', 'Applications'], ['apps-utilities', 'applications', 'Utilities'],
    ['users', 'root', 'Users'], ['home', 'users', 'wilson'], ['desktop', 'home', 'Desktop'],
    ['documents', 'home', 'Documents'], ['downloads', 'home', 'Downloads'], ['pictures', 'home', 'Pictures'],
    ['music', 'home', 'Music'], ['trash', 'home', '.trash'],
  ]
  const seen = new Set(nodes.map((n) => n.id))
  const lines = baseFolders
    .filter(([id]) => !seen.has(id))
    .map(([id, parentId, name]) => `  node({ id: ${JSON.stringify(id)}, parentId: ${JSON.stringify(parentId)}, name: ${JSON.stringify(name)}, kind: 'folder', ageMin: 0 }),`)
  for (const n of nodes) {
    lines.push(
      `  node({ id: ${JSON.stringify(n.id)}, parentId: ${JSON.stringify(n.parentId)}, name: ${JSON.stringify(n.name)}, kind: ${JSON.stringify(n.kind)}` +
        (n.mime ? `, mime: ${JSON.stringify(n.mime)}` : '') +
        (n.content ? `, content: ${JSON.stringify(n.content)}` : '') +
        `, ageMin: ${n.modifiedDeltaMin ?? 0} }),`,
    )
  }
  const out = `${banner('/tmp/extracted/fs-seeds.json')}import type { FsNode } from './stores/fs'

const min = (m: number) => Date.now() - m * 60_000
const node = (o: Omit<FsNode, 'created' | 'modified'> & { ageMin: number }): FsNode => {
  const { ageMin, ...rest } = o
  return { ...rest, created: min(ageMin), modified: min(ageMin) }
}

export const FS_SEED: FsNode[] = [
${lines.join('\n')}
]
`
  writeFileSync('app/src/system/fs-seed.ts', out)
  console.log('app/src/system/fs-seed.ts', nodes.length + 11, 'nodes')
}

// ---------- notes-seed.ts ----------
{
  const notes = read('notes-seeds.json')
  const lines = notes
    .map((n, i) => {
      const fields = [
        `id: 'seed-note-${i + 1}'`,
        `folder: ${JSON.stringify(n.folder)} as NoteFolder`,
        `html: ${JSON.stringify(n.html)}`,
        `tags: ${JSON.stringify(n.tags ?? [])}`,
        n.pinned ? 'pinned: true' : '',
        `created: min(${n.ageMin ?? 60})`,
        `modified: min(${n.ageMin ?? 60})`,
      ].filter(Boolean)
      return `  { ${fields.join(', ')} },`
    })
    .join('\n')
  const out = `${banner('/tmp/extracted/notes-seeds.json')}import type { Note, NoteFolder } from './stores/notes'

const min = (m: number) => Date.now() - m * 60_000

export const NOTES_SEED = (): Note[] => [
${lines}
]
`
  writeFileSync('app/src/system/notes-seed.ts', out)
  console.log('app/src/system/notes-seed.ts', notes.length, 'notes')
}

// ---------- per-app data.ts ----------
const dataFiles = [
  ['mail', 'mail.json', 'mailSeed'],
  ['contacts', 'contacts.json', 'contactsSeed'],
  ['messages', 'messages.json', 'conversationsSeed'],
  ['calendar', 'calendar.json', 'calendarSeed'],
  ['reminders', 'reminders.json', 'remindersSeed'],
  ['music', 'music.json', 'tracksSeed'],
  ['podcasts', 'podcasts.json', 'podcastsSeed'],
  ['photos', 'photos.json', 'photosSeed'],
  ['stocks', 'stocks.json', 'stocksSeed'],
  ['safari', 'safari.json', 'bookmarksSeed'],
  ['news', 'news.json', 'articlesSeed'],
  ['dictionary', 'dictionary.json', 'wordsSeed'],
  ['weather', 'weather.json', 'citiesSeed'],
  ['diskutility', 'disks.json', 'disksSeed'],
]
for (const [app, json, name] of dataFiles) {
  if (!existsSync(`${E}/${json}`)) { console.log(`skip ${app} (${json} missing)`); continue }
  mkdirSync(`app/src/apps/${app}`, { recursive: true })
  const data = readFileSync(`${E}/${json}`, 'utf8')
  writeFileSync(`app/src/apps/${app}/data.ts`, `${banner(json)}export const ${name} = ${data}\n`)
  console.log(`app/src/apps/${app}/data.ts`)
}

// ---------- tv videos ----------
{
  const videos = [
    { name: 'Big Buck Bunny (sample).mp4', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', desc: 'Blender Foundation — classic sample reel' },
    { name: 'Flower (CC0).mp4', url: 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', desc: 'MDN CC0 sample' },
    { name: 'Nature Clip.mp4', url: 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', desc: 'MDN CC0 sample' },
  ]
  mkdirSync('app/src/apps/tv', { recursive: true })
  writeFileSync('app/src/apps/tv/data.ts', `${banner('video objects in bundle')}export const videosSeed = ${JSON.stringify(videos, null, 2)}\n`)
  console.log('app/src/apps/tv/data.ts')
}
